<script setup lang="ts">
import { useQuery,useQueryClient } from '@tanstack/vue-query'
import ExecutionVariables from './ExecutionVariables.vue'
import type { Project } from '~~/shared/types/projects'
import type { ExecutionDocument } from '~~/shared/types/project-execution'
import type { ClosingKind,ClosingCheck,ProjectClosing } from '~~/shared/types/project-closing'
import { closingStateSchema,defaultClosingState,defaultClosingKit,emptyClosingChecks,requiredClosingChecks,closingProgress,renderClosingDocument } from '~~/shared/utils/project-closing'
import { checkDeadline,contractTimeline,timelineLabel } from '~~/shared/utils/project-timeline'
import { todayDate } from '~~/shared/utils/subscriptions'
import { executionMoney } from '~~/shared/utils/project-execution'
const route=useRoute()
const props=defineProps<{project:Project}>(),auth=useAuthStore(),supabase=useNuxtApp().$supabase,client=useQueryClient(),today=useState('subscription-today',()=>todayDate())
const query=useQuery({queryKey:computed(()=>['account',auth.user?.id,'project-closing',props.project.id]),queryFn:({signal})=>sharedRequest<ProjectClosing>(`/api/projects/${props.project.id}/closing`,{signal}),retry:false})
const state=ref(defaultClosingState()),base=ref(''),revision=ref(0),estimateRevision=ref(0),executionRevision=ref(0),loaded=ref(false),selected=ref(String(route.query.contract??'')),kind=ref<ClosingKind>('act'),search=ref(''),error=ref(''),busy=ref(false),exporting=ref(''),templatesOpen=ref(false),templateKind=ref<ClosingKind>('act'),resetOpen=ref(false),previewOpen=ref(true)
const editable=computed(()=>props.project.permission!=='viewer'),dirty=computed(()=>loaded.value&&JSON.stringify(state.value)!==base.value)
function load(data:ProjectClosing){state.value=JSON.parse(JSON.stringify(data.state));base.value=JSON.stringify(data.state);revision.value=data.revision;estimateRevision.value=data.estimateRevision;executionRevision.value=data.executionRevision;loaded.value=true;if(!data.execution.contracts.some(c=>c.id===selected.value))selected.value=data.execution.contracts[0]?.id??''}
watch(()=>query.data.value,data=>{if(data&&!dirty.value)load(data)},{immediate:true})
const contracts=computed(()=>query.data.value?.execution.contracts??[]),contract=computed(()=>contracts.value.find(c=>c.id===selected.value)),visible=computed(()=>contracts.value.filter(c=>`${c.number} ${c.seller} ${c.buyer}`.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru').trim())))
const kit=computed(()=>state.value.kits.find(k=>k.contractId===selected.value)??(contract.value?defaultClosingKit(contract.value):null))
const checks=computed(()=>query.data.value&&kit.value?requiredClosingChecks(query.data.value,kit.value):[])
function progress(id:string){const c=contracts.value.find(c=>c.id===id),k=state.value.kits.find(k=>k.contractId===id)??(c?defaultClosingKit(c):null);return query.data.value&&k?{...contractTimeline(query.data.value,k,today.value),complete:contractTimeline(query.data.value,k,today.value).status==='complete'}:{done:0,total:0,complete:false,status:'pending' as const,overdueCount:0,nextDue:''}}
function due(key:ClosingCheck){return query.data.value&&kit.value?checkDeadline(query.data.value,kit.value,key):''}
function isOverdue(key:ClosingCheck){return !!kit.value&&!kit.value.confirmations[key]&&!!due(key)&&due(key)<today.value}
function setDeadline(key:ClosingCheck,value:string){if(!editable.value)return;const k=ensure();k.deadlines={...k.deadlines,[key]:value}}
const completed=computed(()=>contracts.value.filter(c=>progress(c.id).complete).length)
const document=computed(()=>kind.value==='act'?kit.value?.act:kit.value?.upd.document),title=computed(()=>document.value?.title??state.value.templates[kind.value].title),body=computed(()=>document.value?.body??state.value.templates[kind.value].body)
const rendered=computed(()=>{if(!query.data.value||!contract.value)return null;try{return renderClosingDocument({...query.data.value,state:state.value},selected.value,kind.value)}catch{return null}})
function ensure(){if(!contract.value)throw Error('Выберите договор');let k=state.value.kits.find(k=>k.contractId===selected.value);if(!k){k=defaultClosingKit(contract.value);state.value.kits.push(k)}return k}
function editDoc(key:keyof ExecutionDocument,value:string|null){if(!editable.value)return;const k=ensure();k.confirmations=emptyClosingChecks();const d=kind.value==='act'?k.act:k.upd.document;d[key]=value as never}
function confirm(key:ClosingCheck,checked:boolean){if(editable.value)ensure().confirmations[key]=checked}
function toggleUpd(enabled:boolean){const k=ensure();k.upd.enabled=enabled;k.confirmations=emptyClosingChecks();if(!enabled)kind.value='act'}
function editTemplate(key:'title'|'body',value:string){state.value.templates[templateKind.value][key]=value;state.value.kits.forEach(k=>k.confirmations=emptyClosingChecks())}
function select(id:string){selected.value=id;kind.value='act';error.value=''}
function audit(key:ClosingCheck){const value=query.data.value?.audit[selected.value]?.[key];if(dirty.value)return 'Изменения не сохранены';if(!value)return '';const member=props.project.members.find(m=>m.userId===value.by);return `${member?.fullName||member?.email||'Участник проекта'} · ${new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Moscow'}).format(new Date(value.at))}`}
async function save(){
 if(!editable.value||busy.value)return;const parsed=closingStateSchema.safeParse(state.value);if(!parsed.success){error.value=parsed.error.issues[0]?.message??'Проверьте поля';return}
 busy.value=true;error.value='';const user=auth.user?.id
 try{await sharedRequest(`/api/projects/${props.project.id}/closing`,{method:'PUT',body:{revision:revision.value,estimateRevision:estimateRevision.value,executionRevision:executionRevision.value,state:parsed.data}});if(auth.user?.id!==user)return;const result=await query.refetch();if(result.data)load(result.data);await client.invalidateQueries({queryKey:['account',user,'project-progress',props.project.id]})}catch(e:any){error.value=e?.data?.message||e.message}finally{busy.value=false}
}
async function reload(){if(dirty.value&&!window.confirm('Отменить несохранённые изменения и загрузить актуальные данные?'))return;const result=await query.refetch();if(result.data)load(result.data)}
async function download(format:'docx'|'pdf'){
 if(dirty.value||exporting.value)return;exporting.value=format;error.value='';const user=auth.user?.id
 try{const{data}=await supabase.auth.getSession();if(!data.session||data.session.user.id!==user)throw Error('Войдите в аккаунт');const blob=await $fetch<Blob>(`/api/projects/${props.project.id}/closing/export`,{method:'POST',retry:0,responseType:'blob',headers:{Authorization:`Bearer ${data.session.access_token}`},body:{contractId:selected.value,kind:kind.value,format}});if(auth.user?.id!==user)return;const url=URL.createObjectURL(blob),a=window.document.createElement('a');a.href=url;a.download=`${(rendered.value?.title??'Документ').replace(/[\\/:*?"<>|]/g,'-')}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);const result=await query.refetch();if(result.data&&!dirty.value)load(result.data)}catch(e:any){if(e?.data instanceof Blob){try{error.value=JSON.parse(await e.data.text()).message}catch{error.value='Не удалось сформировать документ'}}else error.value=e?.data?.message||e.message}finally{exporting.value=''}
}
function resetKit(){state.value.kits=state.value.kits.filter(k=>k.contractId!==selected.value);kind.value='act';resetOpen.value=false}
watch(editable,value=>{if(!value){templatesOpen.value=false;resetOpen.value=false;if(query.data.value)load(query.data.value)}})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('Есть несохранённые документы или подтверждения. Покинуть страницу?'))
const kindOptions=[{label:'Акт приёмки',value:'act'},{label:'УПД',value:'upd'}]
</script>
<template>
 <section class="closing-workspace" aria-label="Подтверждение и закрывающие акты проекта">
  <div class="closing-toolbar"><div><h2>Закрытие договоров</h2><p>Акты и УПД формируются из сметы и договоров. Первым — комплект заказчика.</p></div><div class="closing-actions"><UButton label="Обновить" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :disabled="busy" @click="reload"/><UButton label="Шаблоны документов" icon="i-lucide-file-pen-line" color="neutral" variant="outline" :disabled="!loaded||busy" @click="templatesOpen=true"/><UButton v-if="editable" label="Сохранить изменения" :loading="busy" :disabled="!dirty||!loaded" @click="save"/></div></div>
  <UAlert v-if="error" color="error" :description="error" class="mb-4"/><p v-if="query.isPending.value">Загружаем закрывающие документы…</p><UAlert v-else-if="query.error.value" color="error" title="Не удалось загрузить закрытие проекта" :actions="[{label:'Повторить',onClick:reload}]"/>
  <template v-else-if="loaded"><div v-if="!contracts.length" class="closing-empty"><UIcon name="i-lucide-clipboard-check"/><h2>Закрывающие документы появятся после добавления договоров</h2><UButton :to="`/projects/${project.id}/contracts`" label="Открыть договоры"/></div>
   <template v-else><div class="closing-summary"><span><strong>{{completed}}</strong> из {{contracts.length}} договоров подтверждено</span><span>Отметки сохраняют автора и время подтверждения.</span></div>
    <div class="closing-layout"><aside class="closing-sidebar"><UInput v-model="search" icon="i-lucide-search" placeholder="Договор или компания" aria-label="Поиск договора для закрытия" class="w-full"/><p v-if="!visible.length" class="closing-muted py-5">Договоры не найдены</p><template v-for="c in visible" :key="c.id"><button class="closing-contract" :class="`timeline-${progress(c.id).status}`" :aria-pressed="selected===c.id" @click="select(c.id)"><span v-if="c.source==='revenue'" class="closing-primary">Заказчик</span><strong>Договор № {{c.number}}</strong><span>{{c.seller}} → {{c.buyer}}</span><b>{{c.amount===null?'Проверьте смету':executionMoney(c.amount)}}</b><span :class="{'closing-done':progress(c.id).complete}">{{timelineLabel(progress(c.id))}}</span><small v-if="progress(c.id).nextDue">Ближайший срок: {{progress(c.id).nextDue.split('-').reverse().join('.')}}</small></button><hr v-if="c.source==='revenue'" class="customer-divider" aria-label="Поставщики"/></template><NuxtLink :to="`/projects/${project.id}/execution`" class="subscription-card-link">Документы исполнения →</NuxtLink></aside>
     <div v-if="contract&&kit" class="closing-main"><header class="closing-kit-header" :class="`timeline-${progress(selected).status}`"><div><span v-if="contract.source==='revenue'" class="closing-primary">Заказчик</span><h2>Договор № {{contract.number}}</h2><p>{{contract.seller}} → {{contract.buyer}}</p></div><strong>{{contract.amount===null?'—':executionMoney(contract.amount)}}</strong></header>
      <UAlert v-if="contract.issue" color="error" :description="contract.issue" class="mt-4"/><UAlert v-if="query.data.value?.needsReview.includes(selected)" color="warning" title="Нужно повторное подтверждение" description="Смета, договор или документы изменились. Предыдущие отметки больше не подтверждают текущий комплект." class="mt-4"/>
      <section class="closing-confirmations" :class="`timeline-${progress(selected).status}`" aria-label="Подтверждение этапов договора"><div class="closing-section-heading"><h3>Подтверждение этапов договора</h3><span :class="{'closing-done':progress(selected).complete}">{{timelineLabel(progress(selected))}}</span></div><p class="closing-muted">По умолчанию используется срок договора. Для каждого пункта можно выбрать свой срок или очистить дату. Изменения сроков сохраняются вместе с отметками.</p><div v-for="check in checks" :key="check.key" class="closing-check" :class="{'check-overdue':isOverdue(check.key)}"><div class="closing-check-label"><UCheckbox :model-value="kit.confirmations[check.key]" :label="check.label" :disabled="!editable||busy||!!contract.issue" @update:model-value="confirm(check.key,!!$event)"/><small v-if="kit.confirmations[check.key]">{{audit(check.key)}}</small><small v-else-if="isOverdue(check.key)" class="deadline-overdue">Срок просрочен</small></div><UInput :model-value="due(check.key)" type="date" :aria-label="`Срок: ${check.label}`" :disabled="!editable||busy" @update:model-value="setDeadline(check.key,String($event??''))"/></div><UButton v-if="editable" label="Сохранить подтверждения" color="neutral" variant="outline" :disabled="!dirty||busy" :loading="busy" @click="save"/></section>
      <div class="closing-document-tabs"><button :aria-pressed="kind==='act'" @click="kind='act'">Акт приёмки</button><button v-if="kit.upd.enabled" :aria-pressed="kind==='upd'" @click="kind='upd'">УПД</button><UCheckbox :model-value="kit.upd.enabled" label="Включить УПД" :disabled="!editable||busy" @update:model-value="toggleUpd(!!$event)"/></div>
