       <div class="closing-export"><UButton :label="previewOpen?'Скрыть предпросмотр':'Предпросмотр'" icon="i-lucide-eye" color="neutral" variant="outline" @click="previewOpen=!previewOpen"/><div class="closing-actions"><span v-if="dirty" class="closing-muted">Перед экспортом сохраните изменения</span><UButton label="Word" icon="i-lucide-file-text" color="neutral" variant="outline" :disabled="dirty||!!exporting||!rendered" :loading="exporting==='docx'" @click="download('docx')"/><UButton label="PDF" icon="i-lucide-file-down" color="neutral" variant="outline" :disabled="dirty||!!exporting||!rendered" :loading="exporting==='pdf'" @click="download('pdf')"/></div></div>
      </section><article v-if="previewOpen&&rendered" class="closing-preview" aria-label="Предпросмотр закрывающего документа"><h2>{{rendered.title}}</h2><template v-for="(block,index) in rendered.blocks" :key="index"><p v-if="block.type==='text'">{{block.text}}</p><div v-else class="closing-table-scroll"><table><thead><tr><th v-for="(heading,i) in block.headers" :key="i">{{heading}}</th></tr></thead><tbody><tr v-for="(row,j) in block.rows" :key="j"><td v-for="(value,k) in row" :key="k">{{value}}</td></tr></tbody></table></div></template></article>
      <div v-if="editable&&state.kits.some(k=>k.contractId===selected)" class="closing-reset"><UButton label="Сбросить закрывающий комплект" color="neutral" variant="ghost" :disabled="busy" @click="resetOpen=true"/></div>
     </div>
    </div>
   </template>
  </template>
  <UModal v-model:open="templatesOpen" title="Шаблоны закрывающих документов" description="Шаблоны проекта применяются к документам без индивидуального текста. Изменение шаблона снимает подтверждения." :ui="{content:'sm:max-w-3xl'}"><template #body><div class="closing-template-form"><USelect v-model="templateKind" :items="kindOptions" aria-label="Тип закрывающего шаблона"/><UFormField label="Заголовок шаблона"><UInput :model-value="state.templates[templateKind].title" :maxlength="200" :disabled="!editable||busy" class="w-full" @update:model-value="editTemplate('title',String($event))"/></UFormField><UFormField label="Текст шаблона"><UTextarea :model-value="state.templates[templateKind].body" :rows="16" :maxlength="20000" :disabled="!editable||busy" class="w-full" @update:model-value="editTemplate('body',String($event))"/></UFormField><ExecutionVariables :disabled="!editable||busy" @insert="editTemplate('body',state.templates[templateKind].body+'\n{{'+$event+'}}')"/><UButton label="Готово" @click="templatesOpen=false"/><p class="closing-muted">После закрытия нажмите «Сохранить изменения».</p></div></template></UModal>
  <UModal v-model:open="resetOpen" title="Сбросить закрывающий комплект?" description="Индивидуальный текст, номера, даты и отметки этого договора будут сброшены. Документы исполнения и сам договор сохранятся."><template #body><div class="closing-actions"><UButton label="Сбросить" color="error" @click="resetKit();resetOpen=false"/><UButton label="Отмена" color="neutral" variant="outline" @click="resetOpen=false"/></div><p class="closing-muted mt-4">Для применения сброса сохраните изменения.</p></template></UModal>
 </section>
</template>
<style scoped>
