{padding:12px 0;border-top:1px solid #edf0f5;display:flex;justify-content:space-between;gap:14px;align-items:center}.closing-check small{font-size:11px;color:#8292a8;text-align:right}.closing-confirmations>.inline-flex{margin-top:14px}.closing-done{color:#169b7c!important}.closing-document-tabs{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:24px 0}.closing-document-tabs>button{padding:12px 18px;border:1px solid #dce2ea;border-radius:11px;background:white;font-size:14px;font-weight:600}.closing-document-tabs>button[aria-pressed=true]{background:var(--ui-primary,#27263f);color:white;border-color:transparent}.closing-editor{display:grid;gap:20px}.closing-editor .closing-section-heading{margin:0}.closing-meta{display:grid;grid-template-columns:1fr 1fr;gap:18px}.closing-muted{font-size:13px;color:#8797ad;line-height:1.6}.closing-template-form{display:grid;gap:18px}.closing-preview{background:white;border:1px solid #e2e8f0;border-radius:16px;padding:40px;margin-top:24px;overflow-wrap:anywhere;font-size:14px;line-height:1.8}.closing-preview h2{font-size:23px;font-weight:650;color:#172334;margin-bottom:28px}.closing-preview p{white-space:pre-wrap;margin:18px 0}.closing-table-scroll{overflow-x:auto}.closing-preview table{width:100%;border-collapse:collapse;font-size:12px}.closing-preview td,.closing-preview th{padding:10px;border:1px solid #dce2ea;text-align:left}.closing-preview th{background:#f1f3f7}.closing-reset{text-align:right;margin-top:18px}.closing-empty{text-align:center;padding:70px 24px;border:1px solid #e2e8f0;border-radius:24px}.closing-empty>.iconify{font-size:44px}.closing-empty h2{font-size:22px;margin:20px 0 24px}@media(max-width:1200px){.closing-toolbar{flex-direction:column}.closing-layout{grid-template-columns:250px minmax(0,1fr)}.closing-kit-header,.closing-export{align-items:flex-start;flex-direction:column}}@media(max-width:800px){.closing-layout{grid-template-columns:minmax(0,1fr)}.closing-sidebar{max-height:360px;overflow:auto}.closi